/// The protocol methods, for a server to implement. An `Err` is the server's own failure: the
/// caller gets `INTERNAL ERROR`, and the calls after it don't run.
#[allow(async_fn_in_trait)]
pub trait Server {
    type Error;

    /// `write _ at _`, returning `saved revision`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    async fn write_at(&self, path: ScorePath, revision: i64) -> Result<i64, Self::Error>;

    /// `limit _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    async fn limit(&self, value: i64) -> Result<i64, Self::Error>;

    /// `summary _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    async fn summary(&self, value: Summary) -> Result<Summary, Self::Error>;

    /// `boxed _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    async fn boxed(&self, value: BoxOf<i64>) -> Result<BoxOf<i64>, Self::Error>;

    /// `score _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    async fn score(&self, value: Probability) -> Result<Probability, Self::Error>;

    /// `names _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    async fn names(&self, value: Names) -> Result<Names, Self::Error>;
}

/// Runs `request` against `implementation` and writes the response. Every
/// call runs, in order, until one fails with an internal error, which
/// `on_internal_error` hears; the calls after it don't run.
pub async fn handle<S: Server>(
    implementation: &S,
    request: &str,
    mut on_internal_error: impl FnMut(<S as Server>::Error),
) -> String {
    let schema = schema();
    let calls = match anyx_protocol::server::read_request(schema, request) {
        Ok(calls) => calls,
        Err(response) => return response,
    };
    let mut outcomes = Vec::new();
    let mut stopped = false;
    for call in &calls {
        if stopped {
            outcomes.push(anyx_protocol::Outcome::NotRun);
            continue;
        }
        let mut arguments = call.arguments.clone().into_iter();
        let outcome = match call.method {
            0 => anyx_protocol::server::value(
                <S as Server>::write_at(
                    implementation,
                    anyx_protocol::server::argument(&mut arguments),
                    anyx_protocol::server::argument(&mut arguments),
                )
                .await,
            ),
            1 => anyx_protocol::server::value(
                <S as Server>::limit(
                    implementation,
                    anyx_protocol::server::argument(&mut arguments),
                )
                .await,
            ),
            2 => anyx_protocol::server::value(
                <S as Server>::summary(
                    implementation,
                    anyx_protocol::server::argument(&mut arguments),
                )
                .await,
            ),
            3 => anyx_protocol::server::value(
                <S as Server>::boxed(
                    implementation,
                    anyx_protocol::server::argument(&mut arguments),
                )
                .await,
            ),
            4 => anyx_protocol::server::value(
                <S as Server>::score(
                    implementation,
                    anyx_protocol::server::argument(&mut arguments),
                )
                .await,
            ),
            5 => anyx_protocol::server::value(
                <S as Server>::names(
                    implementation,
                    anyx_protocol::server::argument(&mut arguments),
                )
                .await,
            ),
            _ => Ok::<_, <S as Server>::Error>(
                anyx_protocol::server::built_in(schema, call)
                    .expect("the codec read a method of the schema"),
            ),
        };
        let outcome = outcome.unwrap_or_else(|error| {
            on_internal_error(error);
            stopped = true;
            anyx_protocol::Outcome::InternalError
        });
        if anyx_protocol::server::validate_outcome(schema, call, &outcome).is_err() {
            stopped = true;
            outcomes.push(anyx_protocol::Outcome::InternalError);
        } else {
            outcomes.push(outcome);
        }
    }
    anyx_protocol::server::respond(schema, &calls, outcomes)
}

/// Calls the methods of the schema through a [`Transport`], one call per
/// request.
pub struct Client<T> {
    pub transport: T,
}

impl<T: Transport> Client<T> {
    pub fn new(transport: T) -> Self {
        Self { transport }
    }

    /// `write _ at _`, returning `saved revision`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    pub async fn write_at(
        &self,
        path: ScorePath,
        revision: i64,
    ) -> Result<i64, CallError<::std::convert::Infallible, T::Error>> {
        anyx_protocol::client::call(
            &self.transport,
            schema(),
            0,
            vec![path.into_value(), revision.into_value()],
        )
        .await
    }

    /// `limit _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    pub async fn limit(
        &self,
        value: i64,
    ) -> Result<i64, CallError<::std::convert::Infallible, T::Error>> {
        anyx_protocol::client::call(&self.transport, schema(), 1, vec![value.into_value()]).await
    }

    /// `summary _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    pub async fn summary(
        &self,
        value: Summary,
    ) -> Result<Summary, CallError<::std::convert::Infallible, T::Error>> {
        anyx_protocol::client::call(&self.transport, schema(), 2, vec![value.into_value()]).await
    }

    /// `boxed _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    pub async fn boxed(
        &self,
        value: BoxOf<i64>,
    ) -> Result<BoxOf<i64>, CallError<::std::convert::Infallible, T::Error>> {
        anyx_protocol::client::call(&self.transport, schema(), 3, vec![value.into_value()]).await
    }

    /// `score _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    pub async fn score(
        &self,
        value: Probability,
    ) -> Result<Probability, CallError<::std::convert::Infallible, T::Error>> {
        anyx_protocol::client::call(&self.transport, schema(), 4, vec![value.into_value()]).await
    }

    /// `names _`, returning `value`.
    ///
    /// It may change anything, and calling it again may do it again, so don't retry it blindly.
    pub async fn names(
        &self,
        value: Names,
    ) -> Result<Names, CallError<::std::convert::Infallible, T::Error>> {
        anyx_protocol::client::call(&self.transport, schema(), 5, vec![value.into_value()]).await
    }

    /// `SCHEMA`, returning the guide to the schema.
    pub async fn schema(&self) -> Result<String, CallError<::std::convert::Infallible, T::Error>> {
        anyx_protocol::client::call(&self.transport, schema(), 6, vec![]).await
    }

    /// `SCHEMA FILES`, returning the files of the schema, the entry first.
    pub async fn schema_files(
        &self,
    ) -> Result<Vec<SchemaFile>, CallError<::std::convert::Infallible, T::Error>> {
        anyx_protocol::client::call(&self.transport, schema(), 7, vec![]).await
    }
}

